    pub(super) fn common(&self, table: NodeTableIndex) -> &CommonColumns {
        self.tables[table.offset()].common()
    }
    pub(super) fn common_mut(&mut self, table: NodeTableIndex) -> &mut CommonColumns {
        self.tables[table.offset()].common_mut()
    }
    pub(super) fn node(
        &self,
        store: AstStoreId,
        key: NodeKey,
    ) -> Result<(&CommonColumns, PayloadTag), AstStoreError> {
        if key.store() != store {
            return Err(AstStoreError::WrongStore { expected: store, actual: key.store() });
        }
        let index = key.index();
        let table =
            self.tables.get(index.table().offset()).ok_or(AstStoreError::MissingNode(index))?;
        let common = table.common();
        if index.element() >= common.len() {
            return Err(AstStoreError::MissingNode(index));
        }
        Ok((common, table.tag()))
    }
