    pub fn new_identifier(
        &mut self,
        flags: NodeFlags,
        range: TextRange,
        text: TextInput<'_>,
    ) -> Result<NodeKey, AstStoreError> {
        let text = self.texts.encode(&self.source, text)?;
        let index = self.prepare_node(PayloadTag::Identifier)?;
        let columns = self.payloads.identifier_mut(index.table());
        columns.text.reserve(1);
        columns.text.push(text);
        self.text_count += 1;
        Ok(self.push_node(index, Kind::Identifier, flags, range, PayloadTag::Identifier))
    }
