    pub fn new_if_statement(
        &mut self,
        flags: NodeFlags,
        range: TextRange,
        expression: NodeKey,
        then_statement: NodeKey,
        else_statement: Option<NodeKey>,
    ) -> Result<NodeKey, AstStoreError> {
        let expression = self.encode(expression)?;
        let then_statement = self.encode(then_statement)?;
        let else_statement = else_statement.map(|key| self.encode(key)).transpose()?;
        let index = self.prepare_node(PayloadTag::IfStatement)?;
        let columns = self.payloads.if_statement_mut(index.table());
        columns.expression.reserve(1);
        columns.then_statement.reserve(1);
        columns.else_statement.reserve(1);
        columns.expression.push(expression);
        columns.then_statement.push(then_statement);
        columns.else_statement.push(else_statement);
        Ok(self.push_node(index, Kind::IfStatement, flags, range, PayloadTag::IfStatement))
    }
