    pub fn new_keyword_expression(
        &mut self,
        flags: NodeFlags,
        range: TextRange,
        kind: Kind,
    ) -> Result<NodeKey, AstStoreError> {
        if !matches!(
            kind,
            Kind::FalseKeyword
                | Kind::ImportKeyword
                | Kind::NullKeyword
                | Kind::SuperKeyword
                | Kind::ThisKeyword
                | Kind::TrueKeyword
        ) {
            return Err(AstStoreError::UnsupportedPayload(kind));
        }
        let index = self.prepare_node(PayloadTag::KeywordExpression)?;
        Ok(self.push_node(index, kind, flags, range, PayloadTag::KeywordExpression))
    }
    pub fn new_string_literal(
        &mut self,
        flags: NodeFlags,
        range: TextRange,
        text: TextInput<'_>,
        token_flags: TokenFlags,
    ) -> Result<NodeKey, AstStoreError> {
        let text = self.texts.encode(&self.source, text)?;
        let token_flags = token_flags & TokenFlags::StringLiteralFlags;
        let index = self.prepare_node(PayloadTag::StringLiteral)?;
        let columns = self.payloads.string_literal_mut(index.table());
        columns.text.reserve(1);
        columns.token_flags.reserve(1);
        columns.text.push(text);
        columns.token_flags.push(token_flags);
        self.text_count += 1;
        Ok(self.push_node(index, Kind::StringLiteral, flags, range, PayloadTag::StringLiteral))
    }
