    pub fn new_keyword_type_node(
        &mut self,
        flags: NodeFlags,
        range: TextRange,
        kind: Kind,
    ) -> Result<NodeKey, AstStoreError> {
        if !matches!(
            kind,
            Kind::VoidKeyword
                | Kind::AnyKeyword
                | Kind::BooleanKeyword
                | Kind::IntrinsicKeyword
                | Kind::NeverKeyword
                | Kind::NumberKeyword
                | Kind::ObjectKeyword
                | Kind::StringKeyword
                | Kind::SymbolKeyword
                | Kind::UndefinedKeyword
                | Kind::UnknownKeyword
                | Kind::BigIntKeyword
        ) {
            return Err(AstStoreError::UnsupportedPayload(kind));
        }
        let index = self.prepare_node(PayloadTag::KeywordTypeNode)?;
        Ok(self.push_node(index, kind, flags, range, PayloadTag::KeywordTypeNode))
    }
