    pub fn new_jsdoc_parameter_or_property_tag(
        &mut self,
        flags: NodeFlags,
        range: TextRange,
        kind: Kind,
        name: NodeKey,
        is_bracketed: bool,
        type_expression: Option<NodeKey>,
        is_name_first: bool,
        tag_name: NodeKey,
        comment: Option<ListKey>,
    ) -> Result<NodeKey, AstStoreError> {
        if !matches!(kind, Kind::JSDocParameterTag | Kind::JSDocPropertyTag) {
            return Err(AstStoreError::UnsupportedPayload(kind));
        }
        let name = self.encode(name)?;
        let type_expression = type_expression.map(|key| self.encode(key)).transpose()?;
        let tag_name = self.encode(tag_name)?;
        let comment = comment.map(|key| self.encode_list(key)).transpose()?;
        let index = self.prepare_node(PayloadTag::JSDocParameterOrPropertyTag)?;
        let columns = self.payloads.jsdoc_parameter_or_property_tag_mut(index.table());
        columns.name.reserve(1);
        columns.is_bracketed.reserve(1);
        columns.type_expression.reserve(1);
        columns.is_name_first.reserve(1);
        columns.tag_name.reserve(1);
        columns.comment.reserve(1);
        columns.name.push(name);
        columns.is_bracketed.push(is_bracketed);
        columns.type_expression.push(type_expression);
        columns.is_name_first.push(is_name_first);
        columns.tag_name.push(tag_name);
        columns.comment.push(comment);
        Ok(self.push_node(index, kind, flags, range, PayloadTag::JSDocParameterOrPropertyTag))
    }
