    pub fn as_identifier(&self) -> Result<IdentifierView<'a>, AstStoreError> {
        self.check_payload(PayloadTag::Identifier)?;
        Ok(IdentifierView {
            key: self.key,
            offset: self.offset,
            columns: self.payloads.identifier(self.key.index().table()),
            source: self.source,
            texts: self.texts,
        })
    }
